// Gera intro + outro para a Cirlene via fal.ai Veo 3.1
// Input: { production_id, intro_prompt, outro_prompt }

const FAL_KEY   = $env.FAL_KEY;
const MONTAGEM  = $env.MONTAGEM_URL || 'http://montagem:3000';
const REF_IMGS  = [
  $env.CIRLENE_REF_1,
  $env.CIRLENE_REF_2,
  $env.CIRLENE_REF_3,
].filter(Boolean);

const body      = $input.first().json.body || $input.first().json;
const pid       = body.production_id;
const introText = body.intro_prompt;
const outroText = body.outro_prompt;

const sleep = ms => new Promise(r => setTimeout(r, ms));

async function submitFal(prompt) {
  const resp = await fetch('https://queue.fal.run/fal-ai/veo3.1/reference-to-video', {
    method: 'POST',
    headers: {
      'Authorization': `Key ${FAL_KEY}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({
      prompt,
      image_urls: REF_IMGS,
      aspect_ratio: '9:16',
      generate_audio: true,
      resolution: '720p',
    }),
  });
  if (!resp.ok) throw new Error(`fal submit failed: ${resp.status} ${await resp.text()}`);
  return (await resp.json()).request_id;
}

async function pollFal(requestId) {
  const base = 'https://queue.fal.run/fal-ai/veo3.1';
  for (let i = 0; i < 30; i++) {
    await sleep(15_000);
    const r = await fetch(`${base}/requests/${requestId}/status`, {
      headers: { 'Authorization': `Key ${FAL_KEY}` },
    });
    const data = await r.json();
    if (data.status === 'COMPLETED') {
      const res = await fetch(`${base}/requests/${requestId}`, {
        headers: { 'Authorization': `Key ${FAL_KEY}` },
      });
      return (await res.json()).video?.url;
    }
    if (data.status === 'FAILED') throw new Error('fal job failed: ' + JSON.stringify(data));
  }
  throw new Error('fal polling timeout after 7.5min');
}

async function uploadToMinio(falUrl, bucket, key) {
  const r = await fetch(`${MONTAGEM}/upload-from-url`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ url: falUrl, bucket, key }),
  });
  if (!r.ok) throw new Error(`upload failed: ${r.status} ${await r.text()}`);
  return await r.json();
}

// --- Intro ---
console.log(`[${pid}] Submitting INTRO to fal.ai...`);
const introId  = await submitFal(introText);
console.log(`[${pid}] INTRO request_id: ${introId}`);
const introFalUrl = await pollFal(introId);
console.log(`[${pid}] INTRO fal URL: ${introFalUrl}`);
const introResult = await uploadToMinio(introFalUrl, 'cirlene-video', `${pid}/intro.mp4`);

// --- Outro ---
console.log(`[${pid}] Submitting OUTRO to fal.ai...`);
const outroId  = await submitFal(outroText);
console.log(`[${pid}] OUTRO request_id: ${outroId}`);
const outroFalUrl = await pollFal(outroId);
console.log(`[${pid}] OUTRO fal URL: ${outroFalUrl}`);
const outroResult = await uploadToMinio(outroFalUrl, 'cirlene-video', `${pid}/outro.mp4`);

return [{
  json: {
    production_id: pid,
    intro_path: introResult.path,
    intro_url:  introResult.url,
    outro_path: outroResult.path,
    outro_url:  outroResult.url,
  }
}];
